#!/usr/bin/env python

def findJumps (dest, jumps, l, maxHops) :
    if (len(l) > maxHops) :
        return []
    if (dest == sum(l)) :
        return l

    l1 = l[:]
    l2 = l[:]
    l1.append(jumps + 1)
    l2.append(-(jumps + 1))

    ret = findJumps (dest, jumps + 1, l1, maxHops)
    if (len(ret) > 0) :
        return ret
    return findJumps (dest, jumps + 1, l2, maxHops)

maxHops = 0
def findShortest (dest) :
    dest = abs(dest)
    if dest == 0:
        return []
    hops = 0
    total = 0
    while total < dest or (total - dest) % 2 != 0:
        hops += 1
        total += hops
    return [1] * hops

