def findN(sumNum):
    i = 0
    num = 0
    if sumNum < 0:
        sumNum = -sumNum
    while num <= sumNum:
        num += i
        i += 1
    num -= i - 1
    i -= 2
    if num == sumNum:
        print(i)
    else:
        diff = sumNum - num
        diff0 = (i + 1) - diff
        if diff0 % 2 == 0:
            print(i + 1)
        else:
            if i % 2 == 1:
                print(i + 2)
            else:
                print(i + 3)


